def reply_formally_via_prompt(user_message, client):
    return client.chat.completions.create(
        model="base-model",
        messages=[
            {"role": "system", "content": "Always respond in a formal, professional tone."},
            {"role": "user", "content": user_message},
        ],
    )

# APPROACH B: fine-tuning -- behavior is baked into the weights, no instruction needed
def reply_formally_via_finetune(user_message, client):
    return client.chat.completions.create(
        model="formal-tone-finetuned-model",   # trained on many formal-tone example replies
        messages=[
            {"role": "user", "content": user_message},   # no system prompt at all
        ],
    )

eval_results = {
    "refund_reply_quality":   {"before": 0.62, "after": 0.94},   # the TARGET task -- big improvement
    "general_qa_accuracy":    {"before": 0.81, "after": 0.53},   # unrelated -- big regression
    "code_help_quality":      {"before": 0.77, "after": 0.44},   # unrelated -- big regression
    "other_ticket_categories":{"before": 0.73, "after": 0.58},   # even nearby tasks regressed
}

for task, scores in eval_results.items():
    delta = scores["after"] - scores["before"]
    flag = "IMPROVED" if delta > 0 else "REGRESSED"
    print(f"{task}: {scores['before']:.2f} -> {scores['after']:.2f} ({flag}, delta={delta:+.2f})")

