def should_deploy(candidate_scores, baseline_scores, regression_tolerance=0.03):
    target_improved = candidate_scores["target_task"] > baseline_scores["target_task"]
    if not target_improved:
        return False

    for task, baseline_score in baseline_scores.items():
        if task == "target_task":
            continue
        delta = candidate_scores[task] - baseline_score
        if delta < -regression_tolerance:
            print(f"Blocking deploy: {task} regressed by {-delta:.3f}, exceeding tolerance {regression_tolerance}")
            return False

    return True

