class BaseModelServer:
    def __init__(self, base_model_path):
        self.base_model = load_base_model(base_model_path)   # loaded ONCE, large and slow to load
        self._active_adapter_id = None

    def generate(self, customer_id, prompt, adapter_registry):
        if self._active_adapter_id != customer_id:
            adapter_path = adapter_registry[customer_id]       # a small file, megabytes not gigabytes
            self.base_model.load_adapter(adapter_path)
            self._active_adapter_id = customer_id
        return self.base_model.generate(prompt)

