from collections import defaultdict

def build_training_set(tickets, max_examples=5000, max_per_category=200):
    examples = []
    seen_prompts = set()
    category_counts = defaultdict(int)

    for ticket in tickets:
        if ticket.question in seen_prompts:
            continue   # skip near-identical duplicates
        if category_counts[ticket.category] >= max_per_category:
            continue   # cap any single category's share of the dataset

        examples.append({"prompt": ticket.question, "completion": ticket.agent_reply})
        seen_prompts.add(ticket.question)
        category_counts[ticket.category] += 1

        if len(examples) >= max_examples:
            break

    return examples

from collections import Counter

def label_balance(examples, min_fraction):
    counts = Counter(ex["label"] for ex in examples)
    total = sum(counts.values())

    underrepresented = [
        label for label, count in counts.items()
        if total > 0 and (count / total) < min_fraction
    ]

    return {"counts": dict(counts), "underrepresented": underrepresented}

# Example:
examples = [{"label": "positive"}] * 90 + [{"label": "negative"}] * 5 + [{"label": "neutral"}] * 5
print(label_balance(examples, min_fraction=0.10))
# {'counts': {'positive': 90, 'negative': 5, 'neutral': 5}, 'underrepresented': ['negative', 'neutral']}
